  resourceContent: ResourceContent(
    summary: 'L\'administration du personnel regroupe l\'ensemble des tâches liées à la gestion administrative des salariés tout au long de leur cycle de vie dans l\'entreprise : de l\'embauche à la sortie. Elle garantit la conformité légale des actes de gestion et assure le suivi des droits et obligations de chaque salarié.',
    keyConcepts: [
      'Contrat de travail (CDI, CDD)',
      'DPAE',
      'Période d\'essai',
      'Congés payés',
      'Absences et justificatifs',
      'Dossier du personnel',
      'Registre unique du personnel',
      'Médecine du travail',
