  ],
  decisionParams: [
    DecisionParam(id: 'investigation_team', label: 'Taille équipe d\'enquête', description: 'Nombre de personnes dans l\'équipe d\'investigation', type: DecisionType.integer, min: 2, max: 8, defaultValue: 4, step: 1),
    DecisionParam(id: 'budget_securite', label: 'Budget sécurité (FCFA)', description: 'Budget annuel alloué à la prévention et la sécurité', type: DecisionType.currency, min: 1000000, max: 20000000, defaultValue: 5000000, step: 500000),
    DecisionParam(id: 'nb_formations', label: 'Nombre de formations sécurité', description: 'Nombre de sessions de formation sécurité par an', type: DecisionType.integer, min: 1, max: 12, defaultValue: 4, step: 1),
  ],
  successMetrics: [
    SuccessMetric(id: 'taux_accidents', label: 'Taux de fréquence des accidents', unit: '/1000h', description: 'Nombre d\'accidents par million d\'heures travaillées'),
    SuccessMetric(id: 'taux_gravite', label: 'Taux de gravité', unit: 'jours', description: 'Nombre de jours d\'arrêt par accident'),
    SuccessMetric(id: 'taux_conformite', label: 'Taux de conformité sécurité', unit: '%', description: 'Pourcentage de conformité aux normes de sécurité'),
  ],
  decisionPeriods: 4,
  rules: [
    'Chaque période représente une étape du plan d\'action sécurité',
    'Tout accident doit être déclaré dans les 48 heures',
    'Les EPI sont obligatoires dans les zones à risque',
  ],
  constraints: [
    'Document unique obligatoire et à jour',
    'Visite médicale annuelle obligatoire pour tous',
    'Formation sécurité obligatoire pour les nouveaux embauchés',
  ],
  resourceContent: ResourceContent(
    summary: 'La santé et la sécurité au travail est une discipline qui vise à préserver l\'intégrité physique et mentale des salariés. Elle repose sur l\'évaluation des risques professionnels, la mise en place de mesures de prévention, la formation des salariés et le suivi médical. L\'employeur a une obligation légale de sécurité de résultat vis-à-vis de ses salariés, dont le non-respect peut engager sa responsabilité pénale.',
    keyConcepts: [
      'Document Unique d\'Évaluation des Risques (DUER)',
      'CHSCT',
      'Risques professionnels',
      'Équipements de Protection Individuelle (EPI)',
      'Accident du travail',
      'Maladie professionnelle',
      'Prévention des risques',
      'Enquête accident',
    ],
    sections: [
      ResourceSection(title: '1. L\'évaluation des risques professionnels et le DUER', content: 'Le Document Unique d\'Évaluation des Risques (DUER) est un document obligatoire qui recense l\'ensemble des risques professionnels identifiés dans l\'entreprise. Il est établi par l\'employeur avec la participation des salariés et du CHSCT. L\'évaluation des risques se fait en plusieurs étapes : identification des dangers (physiques, chimiques, biologiques, mécaniques, psychosociaux), analyse des risques (probabilité et gravité), classement des risques, définition des actions de prévention prioritaires. Le DUER doit être mis à jour au moins une fois par an et à chaque changement significatif des conditions de travail.'),
      ResourceSection(title: '2. L\'enquête après un accident du travail', content: 'L\'enquête accident est une procédure structurée visant à comprendre les causes d\'un accident pour éviter qu\'il ne se reproduise. Elle doit être menée rapidement (dans les 24 à 48 heures suivant l\'accident) par une équipe pluridisciplinaire. La méthode de l\'arbre des causes est la plus utilisée : elle remonte des faits constatés aux causes profondes en passant par les causes immédiates et les causes latentes (organisationnelles, techniques, humaines). L\'enquête se conclut par un rapport qui décrit les faits, analyse les causes, propose des actions correctives et préventives, et désigne les responsables de leur mise en œuvre avec un calendrier.'),
      ResourceSection(title: '3. La prévention des risques professionnels', content: 'La prévention des risques repose sur les neuf principes généraux définis par le Code du travail : éviter les risques, évaluer ceux qui ne peuvent être évités, combattre les risques à la source, adapter le travail à l\'homme, tenir compte de l\'évolution de la technique, remplacer ce qui est dangereux par ce qui n\'est pas dangereux, planifier la prévention, prendre des mesures de protection collective en priorité, donner les instructions appropriées aux salariés. Les mesures de prévention peuvent être techniques (ventilation, enclenchement, protection des machines), organisationnelles (consignes, modes opératoires) et humaines (formation, information, sensibilisation).'),
      ResourceSection(title: '4. Le CHSCT et le suivi médical', content: 'Le Comité d\'Hygiène, de Sécurité et des Conditions de Travail (CHSCT) est une instance représentative du personnel compétente en matière de santé et sécurité. Il est consulté sur le DUER, le plan de prévention, les projets d\'aménagement et les nouvelles technologies. Il se réunit au minimum une fois par trimestre et après chaque accident grave. Le suivi médical des salariés est assuré par le médecin du travail qui effectue des visites médicales périodiques (annuelles) et des visites de reprise après un arrêt de travail. Le médecin du travail a un rôle de conseil auprès de l\'employeur et des salariés sur les questions de santé au travail.'),
    ],
  ),
);

